import{_ as o,o as a,c as r,aj as e}from"./chunks/framework.Cn87zHeG.js";const i="/onerobot-H1/images/faq/wired-ubuntu-ipv4.png",n="/onerobot-H1/images/faq/wired-windows-properties.jpg",d="/onerobot-H1/images/faq/wired-windows-ipv4.jpg",s="/onerobot-H1/images/faq/network-tool/status-overview.jpg",l="/onerobot-H1/images/faq/network-tool/status-device.jpg",g="/onerobot-H1/images/faq/network-tool/wifi-available.jpg",p="/onerobot-H1/images/faq/network-tool/wifi-connect.jpg",c="/onerobot-H1/images/faq/network-tool/wifi-saved.jpg",h="/onerobot-H1/images/faq/network-tool/hotspot.jpg",m="/onerobot-H1/images/faq/network-tool/robot-config.jpg",b="/onerobot-H1/images/faq/network-tool/ros2-config.jpg",f="/onerobot-H1/images/faq/network-tool/system-ota.jpg",u="/onerobot-H1/images/faq/network-tool/arm-upgrade.jpg",w="/onerobot-H1/images/faq/network-tool/gripper-upgrade.jpg",q="/onerobot-H1/images/faq/network-tool/mcu-upgrade.jpg",F=JSON.parse('{"title":"网络配置与 OTA 使用说明","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"getting-started/network-ota.md","filePath":"getting-started/network-ota.md"}'),_={name:"getting-started/network-ota.md"};function k(P,t,I,W,H,j){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="网络配置与-ota-使用说明" tabindex="-1">网络配置与 OTA 使用说明 <a class="header-anchor" href="#网络配置与-ota-使用说明" aria-label="Permalink to &quot;网络配置与 OTA 使用说明&quot;">​</a></h1><p>网络配置工具是机器人自带的网页，端口为 <strong>8080</strong>。通过它可以连接 WiFi、查看设备与固件版本、设置机器人标识，以及升级整机和配套硬件固件。</p><p>本页适用于 H1 标准版和智能版，具体功能以设备配置为准。首次使用建议先完成<a href="#connect">连接与访问</a>，再查看<a href="#status">状态与版本</a>。日常联网见 <a href="#wifi-connect">WiFi 连接</a>；升级时按下表选择对应页面。</p><table tabindex="0"><thead><tr><th>要做什么</th><th>说明位置</th></tr></thead><tbody><tr><td>查看机器人热点、管理 WiFi</td><td><a href="#hotspot">热点信息</a>、<a href="#wifi-connect">连接 WiFi</a>、<a href="#wifi-manage">已保存网络与断开连接</a></td></tr><tr><td>设置机器人标识、查看 ROS 2 通信配置</td><td><a href="#robot-config">机器人配置</a></td></tr><tr><td>升级整机软件</td><td><a href="#system-ota">OTA 升级</a></td></tr><tr><td>升级机械臂电机、自研夹爪或回充板</td><td><a href="#hardware-upgrade">硬件固件升级</a></td></tr><tr><td>查看升级进度与结果</td><td><a href="#upgrade-status">升级状态与监控</a></td></tr></tbody></table><p>当前推荐使用<a href="./../firmware.html">最新整机固件</a>。网络配置工具的最低支持版本为 <strong>1.0.017.260509</strong>；较早固件可能没有下文中的部分功能，建议先升级。界面中的设备信息、网络名称和文件名以你的机器人为准。<strong>点击截图可查看原图。</strong></p><h2 id="connect" tabindex="-1">连接机器人并打开工具 <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;连接机器人并打开工具 {#connect}&quot;">​</a></h2><p>机器人开机后，将电脑或手机与机器人连接到同一网络，再在浏览器打开对应地址。三种方式任选一种：</p><table tabindex="0"><thead><tr><th>接入方式</th><th>地址</th><th>场景</th></tr></thead><tbody><tr><td>网线直连</td><td><code>http://10.42.0.2:8080</code></td><td>开发 / 调试，先按下方说明配置电脑网卡</td></tr><tr><td>机器人热点</td><td><code>http://192.168.60.1:8080</code></td><td>手机 / 笔记本连接机器人热点后访问</td></tr><tr><td>同一局域网</td><td><code>http://&lt;机器人IP&gt;:8080</code></td><td>电脑与机器人连接同一局域网，机器人 IP 见「状态」页 WiFi 卡片</td></tr></tbody></table><h3 id="wired-direct" tabindex="-1">网线直连：先配置电脑的有线网络 <a class="header-anchor" href="#wired-direct" aria-label="Permalink to &quot;网线直连：先配置电脑的有线网络 {#wired-direct}&quot;">​</a></h3><p>用网线连接电脑与机器人，确认机器人已开机、有线连接已接通，再按电脑系统完成以下设置。<strong>这里修改的是电脑上连接机器人的有线网卡</strong>：电脑使用 <code>10.42.0.1</code>，机器人使用 <code>10.42.0.2</code>，不要把电脑也设置成 <code>10.42.0.2</code>。</p><h4 id="wired-ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#wired-ubuntu" aria-label="Permalink to &quot;Ubuntu {#wired-ubuntu}&quot;">​</a></h4><p>按下图中的 1～5 顺序操作：</p><ol><li>打开「设置」→「网络」。</li><li>在连接机器人的「有线」连接右侧，点击齿轮按钮。</li><li>切换到「IPv4」页签。</li><li>将「IPv4 方式」设为 <strong>「与其他计算机共享」</strong>。</li><li>点击「应用」，再关闭并重新打开该有线连接，使设置生效。</li></ol><p><img src="'+i+'" alt="Ubuntu 有线连接设置：网络 → 有线连接齿轮 → IPv4 → 与其他计算机共享 → 应用"></p><p>重新连接后，在该有线连接的「详细信息」中核对 IPv4 地址。访问 <code>10.42.0.2</code> 时，电脑应位于 <code>10.42.0.0/24</code> 网段，例如 <code>10.42.0.1</code>、子网掩码 <code>255.255.255.0</code>。若共享模式分配到了其他网段，可改选「手动」，填写上述地址和掩码，网关、DNS 留空，再应用并重新连接，用于直连访问机器人页面。</p><h4 id="wired-windows" tabindex="-1">Windows <a class="header-anchor" href="#wired-windows" aria-label="Permalink to &quot;Windows {#wired-windows}&quot;">​</a></h4><ol><li>按 <code>Win + R</code>，输入 <code>ncpa.cpl</code> 并回车，打开「网络连接」。也可以从「控制面板」→「网络和 Internet」→「网络和共享中心」→「更改适配器设置」进入。</li><li>找到<strong>连接机器人的以太网网卡</strong>，右键选择「属性」。选择实际插着网线的物理网卡，不要选择 WLAN 或 VPN 虚拟网卡；名称可能与截图不同。</li></ol><p><img src="'+n+'" alt="Windows 网络连接：右键连接机器人的以太网网卡，选择属性"></p><ol start="3"><li>选中「Internet 协议版本 4（TCP/IPv4）」→「属性」，选择「使用下面的 IP 地址」，填写：</li></ol><table tabindex="0"><thead><tr><th>设置项</th><th>填写内容</th></tr></thead><tbody><tr><td>IP 地址（电脑）</td><td><code>10.42.0.1</code></td></tr><tr><td>子网掩码</td><td><code>255.255.255.0</code></td></tr><tr><td>默认网关</td><td>留空</td></tr><tr><td>首选 / 备用 DNS 服务器</td><td>留空（通过 IP 地址访问机器人页面无需 DNS）</td></tr></tbody></table><ol start="4"><li>点击 IPv4 属性窗口的「确定」，再点击以太网属性窗口的「确定」，保存设置。</li></ol><p><img src="'+d+'" alt="Windows IPv4 属性：电脑 IP 地址为 10.42.0.1，子网掩码为 255.255.255.0，网关与 DNS 留空"></p><p>以上设置用于网线直连。使用机器人热点或同一局域网接入时，按对应方式连接网络即可；有线网卡之后改接普通路由器时，恢复原来的网络设置（通常为自动获取 IP / DNS）。</p><p>配置完成后，在电脑浏览器打开 <a href="http://10.42.0.2:8080" target="_blank" rel="noreferrer">http://10.42.0.2:8080</a>，进入网络配置工具。</p><h2 id="status" tabindex="-1">状态页：查看连接、设备与版本 <a class="header-anchor" href="#status" aria-label="Permalink to &quot;状态页：查看连接、设备与版本 {#status}&quot;">​</a></h2><p>打开工具后进入「状态」页，左侧菜单可切换其他功能。</p><ul><li><strong>WiFi 连接</strong>：查看当前网络名称、连接状态和机器人在该网络中的 IP 地址。</li><li><strong>机器人热点</strong>：查看热点名称、地址、运行状态与加密方式。</li><li><strong>电池</strong>：查看机器人上报的电池状态；出现「未订阅」时，表示当前未收到对应状态数据。</li></ul><p><a href="/onerobot-H1/images/faq/network-tool/status-overview.jpg"><img src="'+s+'" alt="状态页的 WiFi 连接与机器人热点信息"></a></p><p>在「状态」页向下找到 <strong>「机器人信息」→「软件版本」</strong>，即可核对已安装的整机固件。这里还显示设备 ID、机器人 ID、型号和出厂序列号。</p><p><a href="/onerobot-H1/images/faq/network-tool/status-device.jpg"><img src="'+l+'" alt="机器人信息卡片中的软件版本与设备标识"></a></p><p>下方的机械臂电机、回充板软件版本属于对应硬件的固件版本，与整机软件版本分别管理。智能版在具备相应配置时还会显示 <strong>NVIDIA 计算板</strong>状态；未配置该功能的设备不显示此卡片。</p><p>版本查询与升级指引见<a href="./../firmware.html">固件版本</a>。</p><h2 id="wifi-connect" tabindex="-1">连接 WiFi <a class="header-anchor" href="#wifi-connect" aria-label="Permalink to &quot;连接 WiFi {#wifi-connect}&quot;">​</a></h2><ol><li>进入左侧「WiFi 配置」页，查看「可用 WiFi」列表；未找到目标网络时，点击「刷新」重新扫描。</li><li>找到目标网络，点击右侧「连接」。</li><li>在弹出的连接窗口输入该网络的密码，再点击「连接」；开放网络按提示确认即可。</li><li>出现 <code>已成功连接到 &lt;SSID&gt;</code> 后，返回「状态」页核对网络名称和 IP 地址。</li></ol><p><a href="/onerobot-H1/images/faq/network-tool/wifi-available.jpg"><img src="'+g+'" alt="WiFi 配置页的可用网络列表与连接入口"></a></p><p>隐藏或扫描不到的网络，可点击 <strong>「手动连接」</strong>，填写准确的 WiFi 名称（SSID）和密码后连接。</p><p><a href="/onerobot-H1/images/faq/network-tool/wifi-connect.jpg"><img src="'+p+'" alt="手动连接 WiFi：填写网络名称与密码"></a></p><p>使用局域网地址访问工具时，切换 WiFi 可能改变机器人的 IP 地址。连接后请使用新地址访问；也可以通过网线直连或机器人热点重新打开工具。</p><h2 id="wifi-manage" tabindex="-1">管理已保存网络与断开连接 <a class="header-anchor" href="#wifi-manage" aria-label="Permalink to &quot;管理已保存网络与断开连接 {#wifi-manage}&quot;">​</a></h2><p>进入「WiFi 配置」→ <strong>「已保存网络」</strong>：</p><ul><li>点击「连接」，使用该网络已保存的配置连接，无需再次输入密码。</li><li>点击「删除」并确认，移除对应的已保存网络；以后连接该网络时需要重新配置。</li></ul><p><a href="/onerobot-H1/images/faq/network-tool/wifi-saved.jpg"><img src="'+c+'" alt="已保存网络列表中的连接与删除按钮"></a></p><p>需要断开当前 WiFi 时，进入 <strong>「状态」→「WiFi 连接」→「断开」</strong>，核对提示后确认。若网页正通过该 WiFi 访问，连接会随之中断，可改用网线或机器人热点访问。</p><h2 id="hotspot" tabindex="-1">查看机器人热点 <a class="header-anchor" href="#hotspot" aria-label="Permalink to &quot;查看机器人热点 {#hotspot}&quot;">​</a></h2><p>进入左侧「热点配置」页，可查看当前热点名称、IP 地址、运行状态与加密方式。密码默认隐藏。</p><p><a href="/onerobot-H1/images/faq/network-tool/hotspot.jpg"><img src="'+h+'" alt="热点配置页：查看当前热点与密码同步说明"></a></p><ul><li>默认名称形如 <strong><code>H1_&lt;设备ID&gt;</code></strong>，实际名称以页面显示为准，开机自动开启。</li><li><strong>默认状态</strong>：热点开放，无密码。</li><li><strong>通过本工具连接带密码的 WiFi 后</strong>：热点密码自动同步为该 WiFi 的密码。</li><li><strong>通过本工具主动断开 WiFi 后</strong>：热点恢复为无密码；临时掉线不等于主动断开。</li><li>此页用于查看热点信息，热点密码跟随 WiFi 自动同步，<strong>不需要也不支持手动修改</strong>。</li></ul><p>若电脑当前通过机器人热点访问网页，机器人连接或断开 WiFi 后，可能需要使用更新后的密码重新连接热点，再打开 <code>http://192.168.60.1:8080</code>。</p><h2 id="robot-config" tabindex="-1">机器人标识与通信配置 <a class="header-anchor" href="#robot-config" aria-label="Permalink to &quot;机器人标识与通信配置 {#robot-config}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标识</th><th>用途与修改方式</th></tr></thead><tbody><tr><td>设备 ID</td><td>由设备网卡地址生成，工具中不可修改</td></tr><tr><td>机器人 ID</td><td>用户自定义的设备标识，例如 <code>H1-LAB-01</code>，在「机器人配置」页设置</td></tr><tr><td>序列号</td><td>设备出厂标识，在「状态」页查看；修改机器人 ID 不会修改出厂序列号</td></tr></tbody></table><h3 id="robot-id" tabindex="-1">设置机器人 ID 与导出配置 <a class="header-anchor" href="#robot-id" aria-label="Permalink to &quot;设置机器人 ID 与导出配置 {#robot-id}&quot;">​</a></h3><ol><li>进入左侧「机器人配置」页，在「基础配置」中填写机器人 ID。</li><li>点击 <strong>「保存」</strong>，收到保存成功提示后，查看下方「当前配置」确认结果。</li><li>需要放弃尚未保存的输入时，点击「重新加载」，恢复已保存内容。</li><li>需要备份时，点击「配置导出」中的 <strong>「导出 JSON」</strong>，将配置文件保存到电脑。</li></ol><p><a href="/onerobot-H1/images/faq/network-tool/robot-config.jpg"><img src="'+m+'" alt="机器人配置页的基础配置与保存按钮"></a></p><p>导出的 JSON 包含机器人 ID 等基础配置，<strong>不包含 WiFi 密码或 ROS 2 通信中间件配置</strong>。</p><h3 id="ros2-config" tabindex="-1">查看 ROS 2 通信配置 <a class="header-anchor" href="#ros2-config" aria-label="Permalink to &quot;查看 ROS 2 通信配置 {#ros2-config}&quot;">​</a></h3><p>「机器人配置」页的「<strong>ROS 2 通讯中间件</strong>」卡片显示：</p><ul><li><strong>本次启动使用</strong>：机器人此次启动时使用的通信实现。</li><li><strong>已保存配置</strong>：保存后供下次启动使用的配置；保存后尚未重启时，可能与上面的值不同。</li></ul><p>H1 标准版和智能版当前统一使用原生 <strong>Zenoh（<code>rmw_zenoh_cpp</code>）</strong>，日常使用保持默认设置即可。电脑端的配套设置见 <a href="./communication.html">ROS 2 通信配置</a>。</p><p><a href="/onerobot-H1/images/faq/network-tool/ros2-config.jpg"><img src="'+b+'" alt="ROS 2 通讯中间件：本次启动使用、已保存配置与操作按钮"></a></p><details class="details custom-block"><summary>高级操作：确需切换通信中间件时</summary><p>切换可能影响机器人与外部设备的 ROS 2 通信。仅在已确认应用和电脑端的配套要求时操作：</p><ol><li>在「通讯中间件」下拉框中选择配套的通信实现。</li><li>点击该卡片内的「保存」，核对确认提示后确认。</li><li>保存成功后，按页面提示<strong>重启机器人</strong>；页面保存操作不会自动重启。</li><li>重启后重新打开工具，确认「本次启动使用」与「已保存配置」一致，再进行通信检查。</li></ol><p>「重新读取」用于读取当前配置。不要将“保存成功”当作当前运行环境已经切换。</p></details><h2 id="system-ota" tabindex="-1">整机 OTA 升级 <a class="header-anchor" href="#system-ota" aria-label="Permalink to &quot;整机 OTA 升级 {#system-ota}&quot;">​</a></h2><p>「OTA 升级」用于更新<strong>整机软件</strong>，使用厂商提供、与机器人匹配的 <strong><code>.img</code></strong> 升级包。</p><div class="warning custom-block"><p class="custom-block-title">升级前确认</p><p>让机器人停止任务并保持静止，确认供电稳定、升级包与设备匹配。升级过程中不要断电或操作机器人，也不要同时启动其他类型的固件升级。</p></div><ol><li>进入左侧「<strong>OTA 升级</strong>」页，确认顶部显示「空闲，可上传或升级」。</li><li>将 <code>.img</code> 文件拖入上传框，或点击上传框选择文件，等待上传完成。</li><li>在「<strong>已上传的 OTA 包</strong>」列表找到该文件，点击「升级」，核对文件名后确认。</li><li>查看顶部状态和「升级日志」，等待最终结果。<strong>上传完成只代表文件已传入机器人，还需要执行升级。</strong></li><li>日志出现 <strong><code>ota升级成功</code></strong> 后，等待机器人自动重启，再重新连接网页，在「状态」→「机器人信息」中核对软件版本。</li></ol><p><a href="/onerobot-H1/images/faq/network-tool/system-ota.jpg"><img src="'+f+'" alt="整机 OTA 页面：升级包上传、已上传文件与升级日志"></a></p><p>若出现 <code>ota升级失败</code>，保留页面错误信息并联系技术支持。整机、机械臂电机、自研夹爪和回充板固件包分别用于对应页面，不可混用，也不要通过改文件后缀来上传。</p><h2 id="hardware-upgrade" tabindex="-1">机械臂、夹爪与回充板固件升级 <a class="header-anchor" href="#hardware-upgrade" aria-label="Permalink to &quot;机械臂、夹爪与回充板固件升级 {#hardware-upgrade}&quot;">​</a></h2><p>这些页面用于更新对应硬件的固件。先按下表核对设备配置与升级包，再进入相应页面操作；共用上面的<a href="#system-ota">升级前确认事项</a>。</p><table tabindex="0"><thead><tr><th>页面</th><th>升级文件</th><th>适用对象</th></tr></thead><tbody><tr><td>机械臂电机固件升级</td><td>以小写 <code>foc_ota</code> 开头的 <code>.bin</code> 文件</td><td>配套的机械臂电机</td></tr><tr><td>自研夹爪固件升级</td><td>以小写 <code>picker_ota</code> 开头的 <code>.bin</code> 文件</td><td><strong>仅配备自研夹爪的机器人</strong></td></tr><tr><td>回充板固件升级</td><td>配套的 <code>.bin</code> 文件</td><td><strong>仅配备回充板的机器人</strong></td></tr></tbody></table><p>机械臂和夹爪的文件名前缀须符合表中要求，<code>.bin</code> 扩展名不区分大小写。请直接使用厂商提供的匹配文件；不确定硬件型号或升级包用途时，先联系技术支持确认。</p><h3 id="arm-upgrade" tabindex="-1">机械臂电机固件升级 <a class="header-anchor" href="#arm-upgrade" aria-label="Permalink to &quot;机械臂电机固件升级 {#arm-upgrade}&quot;">​</a></h3><ol><li>点击左侧「机械臂电机固件升级」。</li><li>上传以 <code>foc_ota</code> 开头的 <code>.bin</code> 固件，等待文件出现在「已上传的机械臂电机固件」列表中。</li><li>点击对应文件的「升级」，核对文件名并确认。</li><li>查看「升级日志」，等待最终的「<strong>机械臂升级成功</strong>」或「机械臂升级失败」结果。</li></ol><p><a href="/onerobot-H1/images/faq/network-tool/arm-upgrade.jpg"><img src="'+u+'" alt="机械臂电机固件页：文件要求、上传入口与升级操作"></a></p><h3 id="gripper-upgrade" tabindex="-1">自研夹爪固件升级 <a class="header-anchor" href="#gripper-upgrade" aria-label="Permalink to &quot;自研夹爪固件升级 {#gripper-upgrade}&quot;">​</a></h3><p><strong>此功能仅适用于自研夹爪。使用其他型号夹爪时，不要在此页升级。</strong></p><ol><li>点击左侧「自研夹爪固件升级」。</li><li>上传以 <code>picker_ota</code> 开头的 <code>.bin</code> 固件，等待上传完成。</li><li>在「已上传的自研夹爪固件」列表中点击对应文件的「升级」，核对文件名并确认。</li><li>查看「升级日志」，等待最终的「<strong>夹爪升级成功</strong>」或「夹爪升级失败」结果。</li></ol><p>当前页面会由升级程序<strong>自动查询夹爪 CAN ID，无需手动填写</strong>。日志中单独一侧夹爪的结果属于过程信息，应以整次升级的最终结果为准。</p><p><a href="/onerobot-H1/images/faq/network-tool/gripper-upgrade.jpg"><img src="'+w+'" alt="自研夹爪固件升级页：适用提示、文件要求与升级操作"></a></p><h3 id="mcu-upgrade" tabindex="-1">回充板固件升级 <a class="header-anchor" href="#mcu-upgrade" aria-label="Permalink to &quot;回充板固件升级 {#mcu-upgrade}&quot;">​</a></h3><p><strong>仅配备回充板的机器人支持此功能。</strong></p><ol><li>点击左侧「回充板固件升级」。</li><li>上传与回充板匹配的 <code>.bin</code> 固件，等待上传完成。</li><li>在「已上传的回充板固件」列表中点击对应文件的「升级」，核对文件名并确认。</li><li>查看「升级日志」，等待最终的「<strong>回充板升级成功</strong>」或「回充板升级失败」结果。</li></ol><p><a href="/onerobot-H1/images/faq/network-tool/mcu-upgrade.jpg"><img src="'+q+'" alt="回充板固件升级页：适用提示、固件上传与升级日志"></a></p><p>各页的「删除」用于移除机器人中已上传的固件文件，不会卸载已安装的固件。升级期间等待当前操作结束，不要重复上传、删除或启动其他升级。</p><h2 id="upgrade-status" tabindex="-1">查看升级状态与结果 <a class="header-anchor" href="#upgrade-status" aria-label="Permalink to &quot;查看升级状态与结果 {#upgrade-status}&quot;">​</a></h2><p>升级在机器人侧独立执行，重新打开对应升级页面会自动检测并恢复显示状态。<strong>但无论如何都不要给机器人断电。</strong></p><p>「开始监控」用于刷新升级日志，<strong>「停止监控」只停止当前页面的日志刷新，不会取消机器人正在执行的升级</strong>。判断是否结束，应查看最终成功 / 失败结果；不要通过关闭网页或停止监控来中断升级。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>页面打不开、热点密码变化、切换 WiFi 后失联或升级没有反馈时，请查看<a href="./../faq/network-ota.html">网络与升级常见问题</a>。其中<a href="./../faq/network-ota.html#q19">升级无反馈</a>说明了启动等待与故障排查方法。</p>',88)])])}const S=o(_,[["render",k]]);export{F as __pageData,S as default};
